namespace IQ2i\HerseBundle\Bridge\Moka\Generator;

use IQ2i\HerseBundle\Bridge\Moka\Model\EmailTwoFactorTrait;
use Moka\Cms\Generator\ClassDumper\UserClassDumper;
use Moka\Cms\Model\Model;
use Scheb\TwoFactorBundle\Model\Email\TwoFactorInterface;

/**
 * Adds the second factor interface of scheb to the user class generated by Moka.
 *
 * Moka writes the class in one go, without an event or an option to add an interface. The file it wrote is
 * amended, so that nothing of its generator has to be copied here.
 *
 * @internal
 */
final class TwoFactorUserClassDumper extends UserClassDumper
{
    public function dump(Model $model, string $entityDir): void
    {
        parent::dump($model, $entityDir);

        $namer = $model->getClassNamer();
        $file = $entityDir.\DIRECTORY_SEPARATOR.$namer->getUserFolder().\DIRECTORY_SEPARATOR.$namer->getUserShortClassName().'.php';
        $code = file_get_contents($file);
        if (false === $code) {
            throw new \LogicException(\sprintf('The user class generated by Moka was expected in "%s".', $file));
        }

        $amended = preg_replace_callback(
            '/^(class\s+'.preg_quote($namer->getUserShortClassName(), '/').'\b[^\n{]*?)(\s+implements\s+[^\n{]+?)?\s*\{/m',
            static fn (array $match): string => $match[1]
                .('' === ($match[2] ?? '') ? ' implements ' : rtrim($match[2]).', ').'\\'.TwoFactorInterface::class
                ."\n{\n\tuse \\".EmailTwoFactorTrait::class.";\n",
            $code,
            1,
            $count,
        );
        if (1 !== $count || null === $amended) {
            throw new \LogicException(\sprintf('The declaration of the user class generated by Moka was not recognised in "%s".', $file));
        }

        file_put_contents($file, $amended);
    }
}
